384     /**
385      * @dev Get user's investment-based referral level access
386      * @param _user Address of the user
387      * @return maxLevels Maximum referral levels user can earn from based on the sum of their active investments
388      */
389     function getUserReferralLevels(address _user) public view returns (uint256) {
390         uint256 currentActiveInvestmentSum = 0;
391         uint256 investmentCount = users[_user].investments.length;
392         for (uint256 i = 0; i < investmentCount; i++) {
393             if (!users[_user].investments[i].capitalWithdrawn) {
394                 currentActiveInvestmentSum += users[_user].investments[i].amount;
395             }
396         }
397 
398         // If no active investments or sum is less than the first tier, 0 levels.
399         if (currentActiveInvestmentSum < 5 * 10**18) { // Minimum threshold for any level is $5
400             return 0;
401         }
402         
403         // Referral level unlock criteria based on the SUM OF ACTIVE investments
404         // Max 17 levels, with the 17th level unlocking at $1000 USDT active sum
405         if (currentActiveInvestmentSum >= 1000 * 10**18) return 17; // $1000+ USDT
406         if (currentActiveInvestmentSum >= 900 * 10**18) return 16;  // $900+ USDT
407         if (currentActiveInvestmentSum >= 800 * 10**18) return 15;  // $800+ USDT
408         if (currentActiveInvestmentSum >= 700 * 10**18) return 14;  // $700+ USDT
409         if (currentActiveInvestmentSum >= 600 * 10**18) return 13;  // $500+? line 409
410         if (currentActiveInvestmentSum >= 550 * 10**18) return 12;  // $550+ USDT
411         if (currentActiveInvestmentSum >= 500 * 10**18) return 11;  // $500+ USDT
412         if (currentActiveInvestmentSum >= 450 * 10**18) return 10;  // $450+ USDT
413         if (currentActiveInvestmentSum >= 400 * 10**18) return 9;   // $400+ USDT
414         if (currentActiveInvestmentSum >= 350 * 10**18) return 8;   // $350+ USDT
415         if (currentActiveInvestmentSum >= 300 * 10**18) return 7;   // $300+ USDT
416         if (currentActiveInvestmentSum >= 250 * 10**18) return 6;   // $250+ USDT
417         if (currentActiveInvestmentSum >= 200 * 10**18) return 5;   // $200+ USDT
418         if (currentActiveInvestmentSum >= 150 * 10**18) return 4;   // $150+ USDT
419         if (currentActiveInvestmentSum >= 100 * 10**18) return 3;   // $100+ USDT
420         if (currentActiveInvestmentSum >= 50 * 10**18) return 2;    // $50+ USDT
421         // The check for currentActiveInvestmentSum >= 5 * 10**18 is implicitly handled by the first check.
422         // If it passed the initial currentActiveInvestmentSum < 5 * 10**18, it means it's >= 5.
423         return 1; // If >= $5 but less than $50
424     }
