426     function _payReferralCommissions(address _user, uint256 _amount) internal {
427         address referrer = users[_user].referrer;
428         
429         for (uint256 i = 0; i < referralRates.length && referrer != address(0); i++) {
430             uint256 referrerMaxLevels = getUserReferralLevels(referrer);
431             
432             // Only pay commission if referrer's investment level allows this generation
433             if ((i + 1) <= referrerMaxLevels) {
434                 uint256 commission = (_amount * referralRates[i]) / 10000;
435                 
436                 if (commission > 0) { // No need to check contract balance here, only on actual withdrawal
437                     users[referrer].totalReferralEarned += commission; // Still tracks total earned
438                     users[referrer].claimableReferralBonus += commission; // Accrue to claimable balance
439                     emit ReferralBonusAccrued(referrer, _user, i + 1, commission);
440                 }
441             }
442             
443             referrer = users[referrer].referrer;
444         }
445     }
