695     /**
696      * @dev Internal function to get users at a specific network level
697      * @param _user Address of the user whose network to analyze
698      * @param _level Level to get users for
699      * @return usersAtLevel Array of user addresses at the specified level
700      */
701     function _getUsersAtLevel(address _user, uint256 _level) internal view returns (address[] memory) {
702         if (_level == 0) {
703             return users[_user].directReferrals;
704         }
705         
706         // For levels > 0, we need to recursively find users
707         address[] memory previousLevel = _getUsersAtLevel(_user, _level - 1);
708         uint256 totalCount = 0;
709         
710         // First, count total users at this level
711         for (uint256 i = 0; i < previousLevel.length; i++) {
712             totalCount += users[previousLevel[i]].directReferrals.length;
713         }
714         
715         // Create array and populate it
716         address[] memory usersAtLevel = new address[](totalCount);
717         uint256 currentIndex = 0;
718         
719         for (uint256 i = 0; i < previousLevel.length; i++) {
720             address[] memory directRefs = users[previousLevel[i]].directReferrals;
721             for (uint256 j = 0; j < directRefs.length; j++) {
722                 usersAtLevel[currentIndex] = directRefs[j];
723                 currentIndex++;
724             }
725         }
726         
727         return usersAtLevel;
728     }
